const http = require('http');
const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');
const axe = require('axe-core');

const root = process.cwd();
const server = http.createServer((req, res) => {
  const urlPath = req.url === '/' ? '/index.html' : req.url.split('?')[0];
  const filePath = path.join(root, urlPath);
  fs.readFile(filePath, (err, data) => {
    if (err) {
      res.writeHead(404);
      res.end('not found');
      return;
    }
    const ext = path.extname(filePath);
    const type = ext === '.html' ? 'text/html' : ext === '.css' ? 'text/css' : 'application/javascript';
    res.writeHead(200, { 'Content-Type': type });
    res.end(data);
  });
});

(async () => {
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  const { port } = server.address();
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const page = await browser.newPage();
  await page.goto(`http://127.0.0.1:${port}/index.html`, { waitUntil: 'networkidle' });

  const initialHidden = await page.locator('.details').first().evaluate((el) => el.hidden);
  const initialExpanded = await page.locator('.disclosure-trigger').first().getAttribute('aria-expanded');
  if (!initialHidden || initialExpanded !== 'false') throw new Error('Disclosure did not initialize collapsed');

  await page.locator('.disclosure-trigger').first().click();
  const afterOpenHidden = await page.locator('.details').first().evaluate((el) => el.hidden);
  const afterOpenExpanded = await page.locator('.disclosure-trigger').first().getAttribute('aria-expanded');
  if (afterOpenHidden || afterOpenExpanded !== 'true') throw new Error('Disclosure did not open correctly');

  await page.addScriptTag({ content: axe.source });
  const results = await page.evaluate(async () => await window.axe.run());
  const wcag = results.violations.filter((v) => !v.tags.includes('best-practice'));
  const bp = results.violations.filter((v) => v.tags.includes('best-practice'));
  if (wcag.length) {
    console.log(JSON.stringify(wcag.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) }))));
    process.exitCode = 1;
  } else {
    console.log(`axe wcag=0 bp=${bp.length}`);
  }
  await browser.close();
  server.close();
})();
