const http = require('http');
const fs = require('fs');
const path = require('path');
const { chromium } = require('playwright');
const axe = require('axe-core');

const root = process.cwd();
const server = http.createServer((req, res) => {
  const urlPath = req.url === '/' ? '/index.html' : req.url.split('?')[0];
  const filePath = path.join(root, urlPath);
  fs.readFile(filePath, (err, data) => {
    if (err) {
      res.writeHead(404);
      res.end('not found');
      return;
    }
    const ext = path.extname(filePath);
    const type = ext === '.html' ? 'text/html' : ext === '.css' ? 'text/css' : 'application/javascript';
    res.writeHead(200, { 'Content-Type': type });
    res.end(data);
  });
});

(async () => {
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  const { port } = server.address();
  const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const page = await browser.newPage();
  await page.goto(`http://127.0.0.1:${port}/index.html`, { waitUntil: 'networkidle' });

  const buttons = page.locator('.disclosure-trigger');
  const details = page.locator('.details');
  for (let i = 0; i < await details.count(); i++) {
    if (!(await details.nth(i).evaluate((el) => el.hidden))) throw new Error('Panel should start hidden');
    if ((await buttons.nth(i).getAttribute('aria-expanded')) !== 'false') throw new Error('Trigger should start collapsed');
  }

  await buttons.first().click();
  if (await details.first().evaluate((el) => el.hidden)) throw new Error('Panel should open on click');
  if ((await buttons.first().getAttribute('aria-expanded')) !== 'true') throw new Error('Trigger should expand on click');

  await page.keyboard.press('Escape');
  if (!(await details.first().evaluate((el) => el.hidden))) throw new Error('Panel should close on Escape');
  if ((await buttons.first().getAttribute('aria-expanded')) !== 'false') throw new Error('Trigger should collapse on Escape');

  await page.addScriptTag({ content: axe.source });
  const results = await page.evaluate(async () => await window.axe.run());
  const wcag = results.violations.filter((v) => !v.tags.includes('best-practice'));
  const bp = results.violations.filter((v) => v.tags.includes('best-practice'));
  if (wcag.length) {
    console.log(JSON.stringify(wcag.map((v) => ({ id: v.id, impact: v.impact, targets: v.nodes.map((n) => n.target) }))));
    process.exitCode = 1;
  } else {
